.re0-nav-button__glyph {
  display: grid;
  place-items: center;
  inline-size: 23px;
  color: var(--re0-gold);
}

#re0-statusbar-app[data-theme="night"] .re0-nav-button__glyph {
  color: var(--re0-accent-bright);
}

.re0-section-panel {
  min-inline-size: 0;
  padding: clamp(18px, 3.5vw, 38px);
  outline: none;
  background: color-mix(in srgb, var(--re0-panel) 92%, transparent);
  backdrop-filter: blur(13px);
}

.re0-section-view,
.re0-overview-panel {
  display: grid;
  gap: 18px;
  min-inline-size: 0;
  animation: re0-page-in 280ms ease both;
}

.re0-section-heading {
  display: grid;
  grid-template-columns: 1fr;
  gap: 3px;
  padding-block-end: 12px;
  border-block-end: 1px solid var(--re0-line);
}

.re0-section-heading__title {
  margin: 0;
  color: var(--re0-ink);
  font-size: clamp(23px, 4vw, 36px);
  font-weight: 560;
  letter-spacing: .02em;
}

#re0-statusbar-app[data-theme="day"] .re0-section-heading__title {
  font-style: italic;
}

#re0-statusbar-app[data-theme="night"] .re0-section-heading__title {
  text-shadow: 0 0 24px rgb(115 215 237 / 14%);
}

.re0-section-heading__description {
  max-inline-size: 68ch;
  margin: 4px 0 0;
  color: var(--re0-muted);
  font-size: 13px;
  line-height: 1.7;
}

.re0-card,
.re0-record-card,
.re0-person-card,
.re0-objective,
.re0-alert,
.re0-readonly-notice,
.re0-checkpoint {
  min-inline-size: 0;
  border: 1px solid var(--re0-line);
  background: var(--re0-panel);
  box-shadow: 0 10px 26px rgb(42 54 63 / 7%);
}

.re0-card,
.re0-checkpoint {
  padding: clamp(15px, 2.4vw, 22px);
  border-radius: 17px;
}

#re0-statusbar-app[data-theme="day"] :is(.re0-card, .re0-record-card, .re0-person-card) {
  border-radius: 17px 17px 12px 12px;
  background:
    linear-gradient(150deg, rgb(255 255 255 / 55%), transparent 42%),
    var(--re0-panel);
}

#re0-statusbar-app[data-theme="night"] :is(.re0-card, .re0-record-card, .re0-person-card, .re0-checkpoint) {
  border-radius: 4px 16px 4px 16px;
  background:
    linear-gradient(130deg, rgb(108 210 233 / 5%), transparent 35%),
    var(--re0-panel);
  box-shadow: inset 0 0 24px rgb(90 197 225 / 3%), 0 12px 30px rgb(0 4 12 / 20%);
}

.re0-card--inset {
  padding: 0;
  border: 0;
  background: transparent !important;
  box-shadow: none !important;
}

.re0-card__title,
.re0-record-section h3,
.re0-question-list,
.re0-alerts h3 {
  margin: 0 0 12px;
  color: var(--re0-ink);
  font-size: 15px;
  font-weight: 680;
}

.re0-overview-panel__grid,
.re0-triple-grid,
.re0-dossier {
  display: grid;
  grid-template-columns: minmax(220px, .82fr) minmax(320px, 1.45fr);
  gap: 16px;
}

.re0-triple-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.re0-dossier {
  align-items: center;
}

.re0-identity {
  gap: 16px;
}

.re0-identity p,
.re0-person-card p {
  margin: 4px 0 0;
  color: var(--re0-muted);
  line-height: 1.5;
}

.re0-field-list {
  display: grid;
  gap: 0;
  margin: 0;
}

.re0-field-list__row {
  display: grid;
  grid-template-columns: minmax(82px, .45fr) minmax(0, 1fr);
  gap: 12px;
  padding-block: 8px;
  border-block-end: 1px dashed var(--re0-line);
}

.re0-field-list__row:last-child {
  border-block-end: 0;
}

.re0-field-list dt,
.re0-tree dt {
  color: var(--re0-muted);
  font-family: "Segoe UI", "Noto Sans SC", sans-serif;
  font-size: 11px;
}

.re0-field-list dd,
.re0-tree dd {
  min-inline-size: 0;
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--re0-ink);
  line-height: 1.55;
}

.re0-objective {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 15px 18px;
  border-radius: 14px;
}

.re0-objective__mark {
  color: var(--re0-gold);
  font-size: 25px;
}

.re0-objective small,
.re0-objective p {
  display: block;
  margin: 0;
}

.re0-objective small {
  color: var(--re0-muted);
  font-size: 10px;
  letter-spacing: .12em;
}

.re0-objective p {
  margin-block-start: 3px;
  line-height: 1.55;
}

.re0-alerts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.re0-alert {
  display: grid;
  gap: 4px;
  padding: 12px 14px;
  border-inline-start: 3px solid var(--re0-danger);
  border-radius: 8px 14px 14px 8px;
}

.re0-alert span,
.re0-all-clear {
  color: var(--re0-muted);
  font-size: 12px;
  line-height: 1.5;
}

.re0-all-clear {
  grid-column: 1 / -1;
  margin: 0;
  padding: 12px;
  border: 1px dashed var(--re0-line);
  border-radius: 12px;
  text-align: center;
}

.re0-fold-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.re0-fold,
.re0-ability-group,
.re0-death-entry {
  overflow: hidden;
  border: 1px solid var(--re0-line);
  border-radius: 13px;
  background: var(--re0-panel);
}

.re0-fold summary,
.re0-ability-group > summary,
.re0-death-entry > summary {
  min-block-size: 44px;
  padding: 12px 15px;
  color: var(--re0-ink);
  cursor: pointer;
}

.re0-fold p {
  margin: 0;
  padding: 0 15px 16px;
  color: var(--re0-muted);
  line-height: 1.75;
}

.re0-record-section {
  min-inline-size: 0;
}

.re0-record-section__heading,
.re0-ability-group > summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.re0-record-section__heading h3 {
  margin: 0;
}

.re0-count {
  display: inline-grid;
  place-items: center;
  min-inline-size: 25px;
  min-block-size: 25px;
  padding-inline: 7px;
  border: 1px solid var(--re0-line);
  border-radius: 99px;
  color: var(--re0-accent);
  font: 700 11px/1 "Segoe UI", sans-serif;
}

.re0-record-grid,
.re0-people-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-block-start: 11px;
}

.re0-record-grid--single {
  grid-template-columns: 1fr;
}

.re0-record-card,
.re0-person-card {
  padding: 15px;
  border-radius: 15px;
}

.re0-record-card__top {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-block-end: 12px;
  padding-block-end: 9px;
  border-block-end: 1px solid var(--re0-line);
}

.re0-record-card__type {
  color: var(--re0-accent);
  font-size: 11px;
  font-weight: 700;
}

.re0-record-card__id {
  overflow: hidden;
  color: var(--re0-muted);
  font: 10px/1.4 ui-monospace, monospace;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.re0-tree {
  display: grid;
  gap: 5px;
  min-inline-size: 0;
  margin: 0;
  padding: 0;
}

.re0-tree--array {
  padding-inline-start: 18px;
}

.re0-tree__row {
  display: grid;
  grid-template-columns: minmax(86px, .4fr) minmax(0, 1fr);
  gap: 10px;
  padding-block: 5px;
  border-block-end: 1px dotted var(--re0-line);
}

.re0-tree__row:last-child {
  border-block-end: 0;
}

.re0-tree__value {
  overflow-wrap: anywhere;
  color: var(--re0-ink);
}

.re0-empty {
  display: grid;
  place-items: center;
  gap: 4px;
  min-block-size: 118px;
  margin-block-start: 10px;
  padding: 18px;
  border: 1px dashed var(--re0-line);
  border-radius: 14px;
  color: var(--re0-muted);
  text-align: center;
}

.re0-empty p,
.re0-empty strong {
  margin: 0;
}

.re0-empty__sigil {
  color: var(--re0-accent);
  font-size: 22px;
}

.re0-ability-groups {
  display: grid;
  gap: 9px;
}

.re0-ability-group[open] > summary {
  border-block-end: 1px solid var(--re0-line);
}

.re0-ability-group .re0-record-section {
  padding: 12px;
}

.re0-ability-group .re0-record-section__heading {
  display: none;
}

.re0-segmented {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 5px;
  border: 1px solid var(--re0-line);
  border-radius: 14px;
  background: color-mix(in srgb, var(--re0-panel-strong) 70%, transparent);
}

.re0-segmented button {
  flex: 1 1 90px;
  padding: 8px 13px;
  border-radius: 10px;
  background: transparent;
}

.re0-segmented button[aria-pressed="true"] {
  color: var(--re0-panel-strong);
  background: var(--re0-accent);
}

#re0-statusbar-app[data-theme="night"] .re0-segmented button[aria-pressed="true"] {
  color: #07131f;
}

.re0-person-card__top {
  display: flex;
  align-items: center;
  gap: 12px;
}

.re0-person-card__facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  margin-block: 13px;
}

.re0-person-card__facts span {
  display: grid;
  gap: 3px;
  min-inline-size: 0;
  padding: 8px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--re0-accent) 7%, transparent);
}

.re0-person-card__facts small {
  color: var(--re0-muted);
  font-size: 9px;
}

.re0-person-card__facts strong {
  overflow: hidden;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.re0-text-button {
  inline-size: 100%;
  border-block-start: 1px solid var(--re0-line);
  color: var(--re0-accent);
  text-align: start;
  background: transparent;
}

.re0-crisis {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 16px;
  border: 1px solid color-mix(in srgb, var(--re0-danger) 28%, var(--re0-line));
  border-radius: 12px;
  color: var(--re0-danger);
  background: color-mix(in srgb, var(--re0-danger) 7%, transparent);
}

.re0-crisis strong {
  font-size: 20px;
}

.re0-checkpoint {
  border-color: color-mix(in srgb, var(--re0-accent) 28%, var(--re0-line));
}

.re0-sensitive-hint,
.re0-sensitive-data__notice {
  color: var(--re0-muted);
  font-size: 12px;
  line-height: 1.6;
}

.re0-sensitive-data {
  max-block-size: 440px;
  margin-block-start: 12px;
  padding: 14px;
  overflow: auto;
  border: 1px solid var(--re0-line);
  border-radius: 10px;
  background: color-mix(in srgb, var(--re0-panel-strong) 76%, transparent);
}

.re0-death-book {
  padding: 17px;
  border: 1px solid color-mix(in srgb, var(--re0-danger) 25%, var(--re0-line));
  border-radius: 16px;
  background:
    repeating-linear-gradient(0deg, transparent 0 28px, rgb(150 76 86 / 4%) 29px 30px),
    var(--re0-panel);
}

#re0-statusbar-app[data-theme="night"] .re0-death-book {
  border-radius: 4px 19px 4px 19px;
  background:
    repeating-linear-gradient(45deg, transparent 0 34px, rgb(141 91 169 / 4%) 35px 36px),
    rgb(12 17 31 / 80%);
}

.re0-death-entry {
  margin-block-start: 9px;
}

.re0-death-entry > summary {
  display: grid;
  grid-template-columns: auto minmax(120px, 1fr) auto;
  align-items: center;
  gap: 10px;
}

.re0-death-entry > .re0-tree {
  padding: 14px;
  border-block-start: 1px solid var(--re0-line);
}

.re0-death-entry__id {
  color: var(--re0-danger);
  font: 700 10px/1.4 ui-monospace, monospace;
}

.re0-question-list {
  display: grid;
  gap: 9px;
  margin-block-end: 0;
  padding-inline-start: 22px;
}

.re0-question-list li {
  padding-inline-start: 5px;
  color: var(--re0-ink);
  line-height: 1.6;
}

.re0-readonly-notice {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 13px 15px;
  border-color: color-mix(in srgb, var(--re0-accent) 34%, var(--re0-line));
  border-radius: 11px;
}

.re0-readonly-notice span {
  padding: 5px 8px;
  border: 1px solid var(--re0-accent);
  color: var(--re0-accent);
  font: 800 9px/1 "Segoe UI", sans-serif;
  letter-spacing: .13em;
  white-space: nowrap;
}

.re0-readonly-notice p {
  margin: 0;
  color: var(--re0-muted);
  font-size: 12px;
  line-height: 1.55;
}

.re0-coverage-grid {
  margin-block-start: 10px;
}

.re0-button {
  padding: 9px 14px;
  border: 1px solid var(--re0-line);
  border-radius: 10px;
  background: var(--re0-panel-strong);
}

.re0-button--primary {
  border-color: var(--re0-accent);
  color: var(--re0-panel-strong);
  background: var(--re0-accent);
}

#re0-statusbar-app[data-theme="night"] .re0-button--primary {
  color: #07131f;
}

.re0-button--quiet {
  color: var(--re0-accent);
  background: transparent;
}

.re0-button--danger {
  border-color: color-mix(in srgb, var(--re0-danger) 45%, var(--re0-line));
  color: var(--re0-danger);
  background: transparent;
}

.re0-icon-button {
  min-inline-size: 44px;
  padding: 8px;
  border: 1px solid var(--re0-line);
  border-radius: 50%;
  color: var(--re0-muted);
  background: transparent;
}

#re0-statusbar-overlay-root {
  --re0-ink: #eaf5fb;
  --re0-muted: #9aafc1;
  --re0-line: rgb(156 205 226 / 20%);
  --re0-panel: rgb(10 20 35 / 92%);
  --re0-panel-strong: #0d1829;
  --re0-accent: #79d9ee;
  --re0-accent-bright: #b6f4ff;
  --re0-danger: #dc7789;
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: grid;
  place-items: center;
  padding: clamp(10px, 3vw, 28px);
}

#re0-statusbar-overlay-root[data-theme="day"] {
  --re0-ink: #263140;
  --re0-muted: #617081;
  --re0-line: rgb(84 103 119 / 22%);
  --re0-panel: rgb(255 252 244 / 94%);
  --re0-panel-strong: #fffdf8;
  --re0-accent: #3d718c;
  --re0-accent-bright: #7fc1dc;
  --re0-danger: #9b4c55;
}

.re0-overlay-backdrop {
  position: absolute;
  inset: 0;
  background: rgb(3 9 17 / 72%);
  backdrop-filter: blur(8px);
  animation: re0-fade-in 180ms ease both;
}

.re0-dialog {
  position: relative;
  z-index: 1;
  inline-size: min(640px, 100%);
  max-block-size: min(780px, calc(100dvh - 32px));
  overflow: auto;
  border: 1px solid var(--re0-line, rgb(142 203 226 / 30%));
  border-radius: 18px;
  color: var(--re0-ink, #ecf5f8);
  background: var(--re0-panel-strong, #101b2b);
  box-shadow: 0 36px 100px rgb(0 0 0 / 46%);
  animation: re0-dialog-in 240ms cubic-bezier(.2, .76, .2, 1) both;
}

.re0-person-drawer {
  justify-self: end;
  inline-size: min(560px, 94%);
  block-size: min(760px, calc(100dvh - 32px));
  border-radius: 20px 4px 4px 20px;
  padding: 0 20px 24px;
}

.re0-dialog__header {
  position: sticky;
  inset-block-start: 0;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 18px 20px;
  border-block-end: 1px solid var(--re0-line, rgb(142 203 226 / 20%));
  background: color-mix(in srgb, var(--re0-panel-strong, #101b2b) 92%, transparent);
  backdrop-filter: blur(16px);
}

.re0-dialog__header h2 {
  margin: 2px 0 0;
  font-size: 22px;
}

.re0-person-drawer > .re0-tree {
  padding-block-start: 18px;
}

.re0-portrait-form {
  display: grid;
  gap: 14px;
  padding: 20px;
}

.re0-crop-preview {
  position: relative;
  display: grid;
  place-items: center;
  inline-size: 168px;
  block-size: 168px;
  margin-inline: auto;
  overflow: hidden;
  border: 1px solid var(--re0-accent, #79d9ee);
  border-radius: 50%;
  color: var(--re0-accent, #79d9ee);
  font-size: 52px;
  background:
    radial-gradient(circle at 40% 25%, rgb(255 255 255 / 14%), transparent 30%),
    color-mix(in srgb, var(--re0-panel-strong, #101b2b) 84%, var(--re0-accent, #79d9ee));
  box-shadow: inset 0 0 34px rgb(113 211 234 / 10%);
}

.re0-crop-preview__image {
  position: absolute;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
  transition: transform 80ms linear;
}

.re0-input-group,
.re0-range {
  display: grid;
  gap: 6px;
  color: var(--re0-muted, #9aafc1);
  font-size: 12px;
}

.re0-input-group input[type="file"],
.re0-input-group input[type="url"] {
  inline-size: 100%;
  min-block-size: 44px;
  padding: 9px 11px;
  border: 1px solid var(--re0-line, rgb(142 203 226 / 24%));
  border-radius: 9px;
  color: var(--re0-ink, #edf6f9);
  background: color-mix(in srgb, var(--re0-panel-strong, #101b2b) 92%, black 8%);
}

.re0-form-divider {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--re0-muted, #9aafc1);
  font-size: 11px;
}

.re0-form-divider::before,
.re0-form-divider::after {
  content: "";
  flex: 1;
  block-size: 1px;
  background: var(--re0-line, rgb(142 203 226 / 20%));
}

.re0-crop-controls,
.re0-scope-picker {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 13px;
  border: 1px solid var(--re0-line, rgb(142 203 226 / 20%));
  border-radius: 11px;
}

.re0-crop-controls legend,
.re0-scope-picker legend {
  padding-inline: 6px;
  color: var(--re0-ink, #edf6f9);
  font-size: 12px;
}

.re0-range {
  grid-template-columns: 78px 1fr;
  align-items: center;
}

.re0-range input {
  inline-size: 100%;
  accent-color: var(--re0-accent, #79d9ee);
}

.re0-scope-picker label {
  display: flex;
  align-items: center;
  gap: 9px;
  min-block-size: 34px;
  color: var(--re0-muted, #9aafc1);
  font-size: 12px;
}

.re0-form-message {
  min-block-size: 20px;
  margin: 0;
  color: var(--re0-danger, #dc7789);
  font-size: 12px;
}

.re0-dialog__actions {
  flex-wrap: wrap;
  justify-content: flex-end;
}

.re0-dialog__actions .re0-button--danger {
  margin-inline-end: auto;
}

:is(button, input, summary, [tabindex]):focus-visible {
  outline: 2px solid var(--re0-accent-bright, #b6f4ff);
  outline-offset: 3px;
}

.re0-sr-only {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@container (max-width: 700px) {
  #re0-statusbar-app[data-theme="day"] {
    --re0-scene: var(--re0-day-art-mobile, none);
  }

  #re0-statusbar-app[data-theme="night"] {
    --re0-scene: var(--re0-night-art-mobile, none);
  }

  .re0-statusbar {
    border-radius: 18px;
  }

  .re0-statusbar__header {
    align-items: flex-start;
    min-block-size: 74px;
    padding: 13px 14px;
  }

  .re0-brand {
    gap: 9px;
  }

  .re0-brand__sigil {
    inline-size: 42px;
    block-size: 42px;
  }

  .re0-brand h1 {
    max-inline-size: 42vw;
    font-size: 16px;
  }

  .re0-header-controls {
    align-items: flex-end;
    flex-direction: column;
    gap: 3px;
  }

  .re0-theme-button {
    min-block-size: 44px;
    padding-inline: 10px;
    font-size: 11px;
  }

  .re0-auto-button {
    min-block-size: 28px;
    padding: 2px 8px;
    border: 0;
  }

  .re0-compact {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 12px;
    padding: 13px 14px;
  }

  .re0-compact__meters {
    grid-column: 1 / -1;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    order: 3;
  }

  .re0-compact__signals {
    display: none;
  }

  .re0-expand-button {
    padding-inline: 12px;
  }

  .re0-details {
    display: block;
    min-block-size: 0;
  }

  .re0-navigation {
    position: sticky;
    inset-block-start: 0;
    z-index: 6;
    display: flex;
    flex-direction: row;
    gap: 4px;
    padding: 7px 8px;
    overflow-x: auto;
    border-inline-end: 0;
    border-block-end: 1px solid var(--re0-line);
    scrollbar-width: thin;
    scroll-snap-type: inline mandatory;
  }

  .re0-navigation::before {
    display: none;
  }

  .re0-nav-button {
    inline-size: auto;
    min-inline-size: 68px;
    flex: 0 0 auto;
    flex-direction: column;
    gap: 2px;
    padding: 6px 9px;
    font-size: 10px;
    scroll-snap-align: start;
  }

  .re0-nav-button__glyph {
    block-size: 18px;
  }

  .re0-section-panel {
    padding: 18px 13px 22px;
  }

  .re0-overview-panel__grid,
  .re0-triple-grid,
  .re0-dossier,
  .re0-record-grid,
  .re0-people-grid,
  .re0-alerts,
  .re0-fold-grid {
    grid-template-columns: 1fr;
  }

  .re0-dossier {
    gap: 24px;
  }

  .re0-identity--dossier {
    align-items: center;
  }

  .re0-meter-grid {
    grid-template-columns: 1fr;
  }

  .re0-person-card__facts {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .re0-field-list__row,
  .re0-tree__row {
    grid-template-columns: minmax(72px, .42fr) minmax(0, 1fr);
  }

  .re0-death-entry > summary {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .re0-death-entry > summary > :last-child {
    grid-column: 1 / -1;
  }

  #re0-statusbar-overlay-root {
    align-items: end;
    padding: 0;
  }

  .re0-dialog,
  .re0-person-drawer {
    inline-size: 100%;
    max-block-size: min(88dvh, 760px);
    block-size: auto;
    border-radius: 18px 18px 0 0;
  }

  .re0-dialog__actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .re0-dialog__actions .re0-button--primary {
    grid-column: 1 / -1;
    grid-row: 1;
  }

  .re0-dialog__actions .re0-button--danger {
    margin-inline-end: 0;
  }
}

@container (max-width: 390px) {
  .re0-compact__meters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .re0-brand__sigil {
    display: none;
  }

  .re0-brand h1 {
    max-inline-size: 48vw;
  }

  .re0-theme-button {
    max-inline-size: 116px;
  }

  .re0-avatar--hero {
    inline-size: 82px;
    min-inline-size: 82px;
    block-size: 82px;
  }

  .re0-person-card__facts {
    grid-template-columns: 1fr;
  }

  .re0-field-list__row,
  .re0-tree__row {
    grid-template-columns: 1fr;
    gap: 3px;
  }

  .re0-readonly-notice {
    align-items: flex-start;
  }
}

@media (prefers-reduced-motion: reduce) {
  #re0-statusbar-app *,
  #re0-statusbar-app *::before,
  #re0-statusbar-app *::after,
  #re0-statusbar-overlay-root *,
  #re0-statusbar-overlay-root *::before,
  #re0-statusbar-overlay-root *::after {
    scroll-behavior: auto !important;
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .001ms !important;
  }
}

@media (prefers-reduced-data: reduce) {
  .re0-statusbar::before,
  .re0-ambient {
    display: none;
  }
}

[data-re0-statusbar-mount][data-paused="true"] *,
[data-re0-statusbar-mount][data-paused="true"] *::before,
[data-re0-statusbar-mount][data-paused="true"] *::after,
[data-re0-statusbar-mount][data-performance="low"] .re0-ambient * {
  animation-play-state: paused !important;
}

[data-re0-statusbar-mount][data-performance="low"] .re0-ambient--front {
  display: none;
}

@keyframes re0-shimmer {
  to { background-position: -220% 0; }
}

@keyframes re0-dust {
  from { transform: translate3d(-2%, -3%, 0) rotate(0deg); }
  to { transform: translate3d(3%, 5%, 0) rotate(2deg); }
}

@keyframes re0-steam {
  0%, 100% { opacity: 0; transform: translateY(18px) scale(.7); }
  45% { opacity: .65; }
  80% { opacity: 0; transform: translateY(-30px) scale(1.2); }
}

@keyframes re0-snow {
  from { transform: translate3d(-2%, -9%, 0) rotate(0); }
  to { transform: translate3d(3%, 10%, 0) rotate(3deg); }
}

@keyframes re0-butterfly {
  0%, 100% { opacity: .25; transform: translate3d(0, 12px, 0) rotate(-12deg) scale(.82); }
  50% { opacity: .8; transform: translate3d(-14px, -8px, 0) rotate(12deg) scale(1.08); }
}

@keyframes re0-reveal {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes re0-page-in {
  from { opacity: 0; transform: translateX(8px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes re0-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes re0-dialog-in {
  from { opacity: 0; transform: translateY(14px) scale(.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes re0-dawn {
  0% { filter: brightness(.72) saturate(.8); }
  55% { filter: brightness(1.12) saturate(1.03); }
  100% { filter: none; }
}

@keyframes re0-dusk {
  0% { filter: sepia(.16) brightness(1.08); }
  55% { filter: sepia(.22) brightness(.88); }
  100% { filter: none; }
}

</style>
</head>
<body>
<div data-re0-statusbar-mount>
<main id="re0-statusbar-app" aria-live="polite" aria-busy="true"></main>
<div id="re0-statusbar-overlay-root" hidden></div>
<noscript>此状态栏需要启用 JavaScript。</noscript>
</div>
<script>
(() => {
'use strict';

const DECLARED_DOMAIN_COUNTS = Object.freeze({
  世界: 20,
  主角档案: 58,
  轮回: 25,
  关系: 31,
  事件: 13,
  线索: 6,
  资产: 17,
  规则: 2,
});

const ABILITY_CATEGORIES = Object.freeze([
  '加护',
  '权能',
  '魔法',
  '精灵术',
  '种族能力',
  '武技',
  '一般技能',
]);

const FIELD_GROUPS = Object.freeze([
  { domain: '世界', base: '世界.当前时间', fields: ['规范日期', '时段', '时间层', '轮回分支'] },
  { domain: '世界', base: '世界.当前地点', fields: ['国家', '地区', '场所', '具体位置'] },
  { domain: '世界', base: '世界.环境', fields: ['天气', '光照', '描述'] },
  { domain: '世界', base: '世界', fields: ['危机等级'] },
  { domain: '世界', base: '世界.动向.{事件ID}', fields: ['标题', '阶段', '类型', '地点', '描述'] },
  { domain: '世界', base: '世界.势力态势.{势力名称}', fields: ['立场', '状态', '描述'] },

  {
    domain: '主角档案',
    base: '主角档案',
    fields: [
      '主角锁定', '姓名', '角色类型', '性别', '年龄阶段', '种族', '身份', '阵营',
      '容貌', '衣着', '生存状态', '生命', '体力', '魔力', '精神稳定', '门状态',
      '门负荷', '魔女余香',
    ],
  },
  { domain: '主角档案', base: '主角档案.伤势.{伤势ID}', fields: ['部位', '程度', '描述'] },
  { domain: '主角档案', base: '主角档案.异常状态.{状态ID}', fields: ['类型', '剩余表现', '描述'] },
  { domain: '主角档案', base: '主角档案', fields: ['当前形态'] },
  { domain: '主角档案', base: '主角档案.战力等阶', fields: ['阶数', '位阶', '可战状态', '生效条件'] },
  {
    domain: '主角档案',
    base: '主角档案.能力.{类别}.{能力ID}',
    fields: ['状态', '可用性', '消耗或冷却', '描述'],
    variants: { 类别: ABILITY_CATEGORIES },
  },
  { domain: '主角档案', base: '主角档案', fields: ['当前目标'] },

  { domain: '轮回', base: '轮回', fields: ['世界重启次数', '当前轮回编号'] },
  { domain: '轮回', base: '轮回.存档点', fields: ['有效', '创建时间'] },
  {
    domain: '轮回',
    base: '轮回.存档点.状态快照',
    fields: ['世界', '主角档案', '关系', '事件', '线索', '资产'],
    deep: true,
  },
  { domain: '轮回', base: '轮回.最近一次重启', fields: ['死亡事件ID', '重启编号', '触发时间', '恢复结果'] },
  {
    domain: '轮回',
    base: '轮回.菜月昴死亡记录.{死亡ID}',
    fields: [
      '重启编号', '死亡时规范日期与时段', '死亡时地点', '直接原因',
      '死亡经过与最后行动', '在场或相关人物', '触发前轮回分支', '本轮遗留情报',
    ],
  },
  { domain: '轮回', base: '轮回.最近一次死亡', fields: ['死亡ID', '直接原因', '死亡经过'] },

  {
    domain: '关系',
    base: '关系.伴侣.{姓名}',
    fields: ['关系阶段', '亲密度', '立场', '生存状态', '当前地点', '当前行动'],
  },
  {
    domain: '关系',
    base: '关系.契约伙伴.{姓名}',
    fields: ['契约状态', '关系阶段', '信任', '立场', '生存状态', '当前地点', '当前行动'],
  },
  {
    domain: '关系',
    base: '关系.人物.{姓名}',
    fields: [
      '身份', '阵营', '关系阶段', '立场', '好感', '信任', '生存状态',
      '生命', '魔力', '当前地点', '当前行动', '当前形态',
    ],
  },
  { domain: '关系', base: '关系.人物.{姓名}.伤势.{伤势ID}', fields: ['部位', '程度', '描述'] },
  { domain: '关系', base: '关系.人物.{姓名}.异常状态.{状态ID}', fields: ['类型', '剩余表现', '描述'] },

  {
    domain: '事件',
    base: '事件.进行中.{事件ID}',
    fields: ['标题', '类型', '阶段', '状态', '地点', '参与者', '目标', '描述'],
  },
  { domain: '事件', base: '事件.近期记录.{事件ID}', fields: ['标题', '结果', '规范日期', '参与者', '描述'] },

  { domain: '线索', base: '线索.当前线索.{线索ID}', fields: ['标题', '状态', '关联事件', '描述', '下一步'] },
  { domain: '线索', base: '线索', fields: ['未解问题'] },

  { domain: '资产', base: '资产.货币.{货币类型}', fields: ['数量', '持有者', '存放位置'] },
  { domain: '资产', base: '资产.物品.{物品ID}', fields: ['名称', '数量', '持有者', '存放位置', '描述'] },
  { domain: '资产', base: '资产.装备.{装备ID}', fields: ['名称', '持有者', '装备状态', '损耗', '当前效果'] },
  { domain: '资产', base: '资产.据点与存放.{据点ID}', fields: ['名称', '位置', '控制者', '状态'] },

  { domain: '规则', base: '规则', fields: ['schema版本', '初始化完成'] },
]);

function expandVariants(template, variants = {}) {
  let results = [template];
  for (const [name, values] of Object.entries(variants)) {
    const token = `{${name}}`;
    results = results.flatMap((candidate) =>
      candidate.includes(token)
        ? values.map((value) => candidate.replaceAll(token, value))
        : [candidate],
    );
  }
  return results;
}

function expandDeclaredPaths() {
  return FIELD_GROUPS.flatMap((group) =>
    expandVariants(group.base, group.variants).flatMap((base) =>
      group.fields.map((field) => `${base}.${field}${group.deep ? '.**' : ''}`),
    ),
  );
}

const DECLARED_PATHS = Object.freeze(expandDeclaredPaths());

function isPlaceholder(segment) {
  return /^\{[^{}]+\}$/.test(segment);
}

function matchesPattern(pattern, path) {
  const expected = pattern.split('.');
  const actual = path.split('.');
  const deep = expected.at(-1) === '**';
  const expectedLength = deep ? expected.length - 1 : expected.length;
  if ((!deep && actual.length !== expectedLength) || (deep && actual.length < expectedLength)) {
    return false;
  }

  for (let index = 0; index < expectedLength; index += 1) {
    if (!isPlaceholder(expected[index]) && expected[index] !== actual[index]) return false;
    if (isPlaceholder(expected[index]) && !actual[index]) return false;
  }
  return true;
}

function isDeclaredPath(path) {
  if (typeof path !== 'string' || !path) return false;
  return DECLARED_PATHS.some((pattern) => matchesPattern(pattern, path));
}


const NAV_SECTIONS = Object.freeze([
  { id: 'overview', label: '概览', glyph: '✦' },
  { id: 'protagonist', label: '主角', glyph: '♙' },
  { id: 'world', label: '世界', glyph: '⌖' },
  { id: 'relations', label: '人际', glyph: '♢' },
  { id: 'loop', label: '轮回', glyph: '∞' },
  { id: 'events', label: '事件', glyph: '◇' },
  { id: 'clues', label: '线索', glyph: '⌕' },
  { id: 'assets', label: '行囊', glyph: '▣' },
  { id: 'diagnostics', label: '诊断', glyph: '⚙' },
]);

function asRecord(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function asList(value) {
  return Array.isArray(value) ? value : [];
}

function asText(value, fallback = '未记录') {
  return typeof value === 'string' && value.trim() ? value.trim() : fallback;
}

function clampMeter(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.min(100, Math.max(0, number)) : fallback;
}

function clampSignedMeter(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.min(100, Math.max(-100, number)) : fallback;
}

function resolveTheme(period, preference = 'auto') {
  const normalizedPeriod = asText(period, '时段未详');
  const transition = normalizedPeriod === '黎明'
    ? 'dawn'
    : normalizedPeriod === '傍晚'
      ? 'dusk'
      : 'steady';
  const automatic = ['夜间', '深夜', '凌晨'].includes(normalizedPeriod) ? 'night' : 'day';
  const normalizedPreference = ['day', 'night'].includes(preference) ? preference : 'auto';
  return {
    mode: normalizedPreference === 'auto' ? automatic : normalizedPreference,
    automatic,
    transition,
    preference: normalizedPreference,
    period: normalizedPeriod,
  };
}

function firstGrapheme(name) {
  const normalized = asText(name, '').trim();
  if (!normalized) return '?';
  if (typeof Intl !== 'undefined' && typeof Intl.Segmenter === 'function') {
    const segment = new Intl.Segmenter('zh-CN', { granularity: 'grapheme' })
      .segment(normalized)[Symbol.iterator]().next().value;
    if (segment?.segment) return segment.segment;
  }
  return Array.from(normalized)[0] || '?';
}

function flattenLeaves(value, prefix = '', output = []) {
  if (Array.isArray(value)) {
    if (prefix) output.push({ path: prefix, value });
    return output;
  }
  if (value && typeof value === 'object') {
    for (const [key, child] of Object.entries(value)) {
      flattenLeaves(child, prefix ? `${prefix}.${key}` : key, output);
    }
    return output;
  }
  if (prefix) output.push({ path: prefix, value });
  return output;
}

function collectUnknownPaths(statData) {
  return flattenLeaves(asRecord(statData)).filter((entry) => !isDeclaredPath(entry.path));
}

function recordEntries(value, category) {
  return Object.entries(asRecord(value)).map(([id, item]) => ({
    id,
    category,
    ...asRecord(item),
  }));
}

function relationshipEntries(relations) {
  return [
    ...recordEntries(relations.伴侣, '伴侣').map((person) => ({ name: person.id, ...person })),
    ...recordEntries(relations.契约伙伴, '契约伙伴').map((person) => ({ name: person.id, ...person })),
    ...recordEntries(relations.人物, '人物').map((person) => ({ name: person.id, ...person })),
  ];
}

function buildInstruments(protagonist) {
  return [
    { id: 'life', label: '生命', value: clampMeter(protagonist.生命), tone: 'vital' },
    { id: 'stamina', label: '体力', value: clampMeter(protagonist.体力), tone: 'stamina' },
    { id: 'mana', label: '魔力', value: clampMeter(protagonist.魔力), tone: 'mana' },
    { id: 'spirit', label: '精神稳定', value: clampMeter(protagonist.精神稳定), tone: 'spirit' },
    { id: 'gate', label: '门负荷', value: clampMeter(protagonist.门负荷), tone: 'risk', inverse: true },
    { id: 'scent', label: '魔女余香', value: clampMeter(protagonist.魔女余香), tone: 'witch', inverse: true },
  ];
}

function buildAlerts(world, protagonist, events) {
  const alerts = [];
  if (!['无', '低'].includes(asText(world.危机等级, '无'))) {
    alerts.push({ kind: 'crisis', title: `${world.危机等级}危机`, detail: asText(world.环境?.描述, '周遭风险正在升高') });
  }
  for (const [id, injury] of Object.entries(asRecord(protagonist.伤势))) {
    const item = asRecord(injury);
    alerts.push({ kind: 'injury', title: `${asText(item.部位, id)} · ${asText(item.程度)}`, detail: asText(item.描述, '伤势详情未记录') });
  }
  for (const [id, abnormal] of Object.entries(asRecord(protagonist.异常状态))) {
    const item = asRecord(abnormal);
    alerts.push({ kind: 'abnormal', title: asText(item.类型, id), detail: asText(item.剩余表现) });
  }
  for (const [id, event] of Object.entries(asRecord(events.进行中))) {
    const item = asRecord(event);
    if (['紧急', '危险', '失控'].some((word) => asText(item.状态, '').includes(word))) {
      alerts.push({ kind: 'event', title: asText(item.标题, id), detail: asText(item.状态) });
    }
  }
  return alerts.slice(0, 3);
}

function buildOverview(world, protagonist, loop, events) {
  const time = asRecord(world.当前时间);
  const location = asRecord(world.当前地点);
  const environment = asRecord(world.环境);
  return {
    time: {
      date: asText(time.规范日期),
      period: asText(time.时段, '时段未详'),
      layer: asText(time.时间层, '主线'),
      branch: asText(time.轮回分支, 'B00'),
    },
    location: [location.国家, location.地区, location.场所, location.具体位置]
      .map((value) => asText(value, ''))
      .filter(Boolean),
    environment: {
      weather: asText(environment.天气),
      light: asText(environment.光照),
      description: asText(environment.描述),
    },
    crisis: asText(world.危机等级, '无'),
    protagonist: {
      name: asText(protagonist.姓名),
      identity: asText(protagonist.身份),
      status: asText(protagonist.生存状态, '存活'),
      form: asText(protagonist.当前形态, '常态'),
      locked: protagonist.主角锁定 === true,
    },
    instruments: buildInstruments(protagonist),
    target: asText(protagonist.当前目标, '无'),
    loop: {
      number: Math.max(0, Number(loop.当前轮回编号) || 0),
      restarts: Math.max(0, Number(loop.世界重启次数) || 0),
      checkpointValid: asRecord(loop.存档点).有效 === true,
    },
    alerts: buildAlerts(world, protagonist, events),
  };
}

function abilityGroups(protagonist) {
  const abilities = asRecord(protagonist.能力);
  return ABILITY_CATEGORIES.map((category) => ({
    category,
    items: recordEntries(abilities[category], category),
  }));
}

function buildHudModel(statData, uiState = {}) {
  const root = asRecord(statData);
  const world = asRecord(root.世界);
  const protagonist = asRecord(root.主角档案);
  const loop = asRecord(root.轮回);
  const relations = asRecord(root.关系);
  const events = asRecord(root.事件);
  const clues = asRecord(root.线索);
  const assets = asRecord(root.资产);
  const rules = asRecord(root.规则);
  const time = asRecord(world.当前时间);

  return Object.freeze({
    readOnly: true,
    theme: resolveTheme(time.时段, uiState.themePreference),
    sections: NAV_SECTIONS,
    overview: buildOverview(world, protagonist, loop, events),
    protagonist: {
      raw: protagonist,
      injuries: recordEntries(protagonist.伤势, '伤势'),
      abnormalities: recordEntries(protagonist.异常状态, '异常状态'),
      abilities: abilityGroups(protagonist),
    },
    world: {
      raw: world,
